import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec4, float, mix } from 'three/tsl';
import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-2';

  const width = 2.4;
  const height = 1.5;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  const map = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const uvNode = uv();

  // Engineered gradient overlay: subtle vertical gradient from surface to ink,
  // blended with the base texture for a machined-metal feel.
  const surfaceColor = vec4(0.043, 0.043, 0.063, 1.0); // #0b0b10
  const inkColor = vec4(0.086, 0.086, 0.114, 1.0); // #16161d
  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  let colorNode;
  if (map) {
    const texColor = texture(map, uvNode);
    colorNode = mix(texColor, gradient, float(0.12));
  } else {
    colorNode = gradient;
  }

  material.colorNode = colorNode;
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-card-2-plane';
  group.add(mesh);

  group.position.set(3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) {
      map.dispose();
    }
  };

  return group;
}
